package com.papaya.claims.workflow;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;

/** Parses and validates workflow YAML once at application startup. */
public final class WorkflowConfigLoader {
    private static final Set<String> ROLES = Set.of("document_clerk", "team_lead", "assessor", "finance", "system");
    private static final Set<String> GUARDS = Set.of("all_required_documents_present", "assessor_assigned",
            "assessment_report_complete", "amount_within_policy_limit", "rejection_reason_present",
            "information_description_present", "new_information_received", "payment_request_exists",
            "payment_confirmed", "appeal_period_expired_or_member_acknowledged");
    private static final Set<String> EFFECTS = Set.of("notify_assessor_team", "record_assessment_start",
            "notify_member_approval", "create_payment_request", "notify_member_rejection",
            "notify_information_request", "reset_assessment_timer", "trigger_payment_system",
            "notify_member_payment_reference", "archive_claim");

    public WorkflowDefinition load(InputStream input) {
        LoaderOptions options = new LoaderOptions(); options.setAllowDuplicateKeys(false);
        Object root = new Yaml(new SafeConstructor(options)).load(input);
        Map<?, ?> rootMap = map(root, "root"); Map<?, ?> workflow = map(rootMap.get("workflow"), "workflow");
        String version = string(workflow.get("version"), "workflow.version");
        String initial = string(workflow.get("initial-state"), "workflow.initial-state");
        LinkedHashSet<String> states = new LinkedHashSet<>();
        for (Object value : list(workflow.get("states"), "workflow.states")) {
            String state = string(value, "state"); if (!states.add(state)) fail("Duplicate state: " + state);
        }
        if (!states.contains(initial)) fail("Unknown initial state: " + initial);
        Map<String,String> guards = stringMap(workflow.get("guard-catalog"), "guard-catalog");
        Map<String,String> effects = stringMap(workflow.get("effect-catalog"), "effect-catalog");
        guards.keySet().forEach(id -> { if (!GUARDS.contains(id)) fail("Unknown guard strategy: " + id); });
        effects.keySet().forEach(id -> { if (!EFFECTS.contains(id)) fail("Unknown effect strategy: " + id); });
        List<WorkflowDefinition.Transition> transitions = new ArrayList<>(); Set<String> ids = new LinkedHashSet<>(), pairs = new LinkedHashSet<>();
        for (Object item : list(workflow.get("transitions"), "transitions")) {
            Map<?, ?> t = map(item, "transition"); String id = string(t.get("id"), "transition.id");
            String from = string(t.get("from"), id + ".from"), to = string(t.get("to"), id + ".to");
            if (!ids.add(id)) fail("Duplicate transition id: " + id);
            if (!states.contains(from) || !states.contains(to)) fail("Transition " + id + " references unknown state");
            if (!pairs.add(from + "\u0000" + to)) fail("Duplicate transition pair: " + from + " -> " + to);
            Set<String> roles = new LinkedHashSet<>(); for (Object r : list(t.get("authorized-roles"), id + ".authorized-roles")) {
                String role = string(r, id + ".role"); if (!ROLES.contains(role)) fail("Unknown role: " + role); roles.add(role);
            }
            if (roles.isEmpty()) fail("Transition " + id + " requires at least one role");
            List<String> guardIds = strings(t.get("guards"), id + ".guards"), effectIds = strings(t.get("effects"), id + ".effects");
            guardIds.forEach(g -> { if (!guards.containsKey(g)) fail("Unknown guard: " + g); });
            effectIds.forEach(e -> { if (!effects.containsKey(e)) fail("Unknown effect: " + e); });
            transitions.add(new WorkflowDefinition.Transition(id, from, to, roles, guardIds, effectIds));
        }
        Map<?, ?> c = map(workflow.get("cycle-policy"), "cycle-policy");
        String cycleId = string(c.get("transition-id"), "cycle-policy.transition-id");
        String counter = string(c.get("counter"), "cycle-policy.counter"); int maximum = integer(c.get("maximum"), "cycle-policy.maximum");
        String message = string(c.get("error-message"), "cycle-policy.error-message");
        if (maximum < 1 || transitions.stream().noneMatch(t -> t.id().equals(cycleId))) fail("Invalid cycle policy transition or maximum");
        if (!"informationRequests".equals(counter)) fail("Unsupported cycle counter: " + counter);
        if (!message.equals("Maximum information requests exceeded — escalate to team lead")) fail("Cycle policy error message does not match the required contract");
        return new WorkflowDefinition(version, initial, states, guards, effects, transitions,
                new WorkflowDefinition.CyclePolicy(cycleId, counter, maximum, message));
    }
    private static Map<String,String> stringMap(Object value, String name) {
        Map<?,?> source = map(value, name); Map<String,String> result = new LinkedHashMap<>();
        source.forEach((k,v) -> result.put(string(k,name+" key"), string(v,name+" value"))); return result;
    }
    private static List<String> strings(Object value, String name) { List<String> result = new ArrayList<>(); for(Object v:list(value,name)) result.add(string(v,name)); return result; }
    private static Map<?,?> map(Object v,String n) { if (!(v instanceof Map<?,?> m)) throw new IllegalArgumentException("Malformed workflow configuration: expected mapping at " + n); return m; }
    private static List<?> list(Object v,String n) { if (!(v instanceof List<?> l)) throw new IllegalArgumentException("Malformed workflow configuration: expected list at " + n); return l; }
    private static String string(Object v,String n) { if (!(v instanceof String s) || s.isBlank()) throw new IllegalArgumentException("Malformed workflow configuration: expected nonblank string at " + n); return s; }
    private static int integer(Object v,String n) { if (!(v instanceof Number number)) throw new IllegalArgumentException("Malformed workflow configuration: expected integer at " + n); try { return new java.math.BigDecimal(number.toString()).intValueExact(); } catch (ArithmeticException e) { throw new IllegalArgumentException("Malformed workflow configuration: expected integer at " + n,e); } }
    private static void fail(String message) { throw new IllegalArgumentException("Invalid workflow configuration: " + message); }
}
