package com.papaya.claims.workflow;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Predicate;
import com.papaya.claims.claim.domain.ClaimFacts;

/** Registry-backed guard strategies. All values come from the authorized merged claim and trusted evidence. */
public final class GuardEvaluator {
    private final Map<String, Predicate<WorkflowEvaluationContext>> strategies;
    public GuardEvaluator() {
        Map<String, Predicate<WorkflowEvaluationContext>> m = new LinkedHashMap<>();
        m.put("all_required_documents_present", c -> documentsPass(c.claim().facts()));
        m.put("assessor_assigned", c -> nonblank(c.claim().facts().values().get("assessorId")));
        m.put("assessment_report_complete", c -> {
            Object report = c.claim().facts().values().get("assessmentReport");
            return report instanceof Map<?,?> map && Boolean.TRUE.equals(map.get("complete"));
        });
        m.put("amount_within_policy_limit", c -> {
            Object value = c.claim().facts().values().get("requestedAmount");
            if (!(value instanceof BigDecimal amount)) return false;
            return amount.signum() >= 0 && amount.compareTo(c.claim().policyLimit()) <= 0;
        });
        m.put("rejection_reason_present", c -> !c.command().reason().isBlank());
        m.put("information_description_present", c -> !c.command().reason().isBlank());
        m.put("new_information_received", c -> after(c.evidence().lastInformationReceivedAt(), c.evidence().lastInformationRequestedAt()));
        m.put("payment_request_exists", c -> c.evidence().paymentRequestExists());
        m.put("payment_confirmed", c -> c.evidence().paymentRequestExists() && nonblank(c.evidence().paymentReference()) && c.evidence().paymentConfirmedAt() != null);
        m.put("appeal_period_expired_or_member_acknowledged", c -> {
            Instant rejected = c.evidence().rejectedAt(); if (rejected == null) return false;
            Instant acknowledged = c.evidence().memberAcknowledgedRejectionAt();
            return !c.now().isBefore(rejected.plus(c.appealPeriod())) || (acknowledged != null && !acknowledged.isBefore(rejected));
        });
        strategies = Map.copyOf(m);
    }
    public boolean passes(String id, WorkflowEvaluationContext context) {
        Predicate<WorkflowEvaluationContext> strategy = strategies.get(id);
        if (strategy == null) throw new IllegalArgumentException("Unknown guard strategy: " + id);
        return strategy.test(context);
    }
    public boolean supports(String id) { return strategies.containsKey(id); }
    private static boolean after(Instant value, Instant baseline) { return value != null && baseline != null && value.isAfter(baseline); }
    private static boolean nonblank(Object value) { return value instanceof String s && !s.isBlank(); }
    private static boolean documentsPass(ClaimFacts facts) {
        Object raw = facts.values().get("documents"); if (!(raw instanceof Map<?,?> docs) || docs.isEmpty()) return false;
        boolean anyRequired = false;
        for (Map.Entry<?,?> entry : docs.entrySet()) {
            if (!(entry.getKey() instanceof String id) || !id.matches("[A-Za-z0-9][A-Za-z0-9._:-]{0,119}") || !(entry.getValue() instanceof Map<?,?> doc)) return false;
            Object required = doc.get("required"), present = doc.get("present"), valid = doc.get("valid");
            if (!(required instanceof Boolean) || !(present instanceof Boolean) || !(valid instanceof Boolean)) return false;
            if (Boolean.TRUE.equals(required)) { anyRequired = true; if (!Boolean.TRUE.equals(present) || !Boolean.TRUE.equals(valid)) return false; }
        }
        return anyRequired;
    }
}
