package com.papaya.claims.workflow;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Pure configured state-machine interpreter; contains no state-specific branches or I/O. */
public final class WorkflowEngine {
    private final WorkflowDefinition definition;
    private final GuardEvaluator guards;
    private final Map<String, EffectStrategy> effects;
    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards) {
        this.definition = java.util.Objects.requireNonNull(definition); this.guards = java.util.Objects.requireNonNull(guards);
        Map<String,EffectStrategy> registry = new LinkedHashMap<>();
        definition.effects().keySet().forEach(id -> registry.put(id, () -> id));
        this.effects = Map.copyOf(registry);
        for (WorkflowDefinition.Transition transition : definition.transitions()) {
            transition.guards().forEach(id -> { if (!guards.supports(id)) throw new IllegalArgumentException("Unknown guard strategy: " + id); });
            transition.effects().forEach(id -> { if (!effects.containsKey(id)) throw new IllegalArgumentException("Unknown effect strategy: " + id); });
        }
    }
    public List<WorkflowOption> availableTransitions(WorkflowEvaluationContext context) {
        List<WorkflowOption> options = new ArrayList<>();
        for (WorkflowDefinition.Transition t : definition.transitions()) if (t.from().equals(context.claim().state())) {
            List<String> failures = failures(t, context);
            options.add(new WorkflowOption(t.id(), t.to(), t.roles(), failures.isEmpty(), failures));
        }
        return List.copyOf(options);
    }
    public WorkflowDecision evaluate(WorkflowEvaluationContext context) {
        String from = context.claim().state(), to = context.command().targetState();
        WorkflowDefinition.Transition selected = definition.transitions().stream()
                .filter(t -> t.from().equals(from) && t.to().equals(to)).findFirst().orElse(null);
        if (selected == null) {
            String available = String.join(", ", definition.transitions().stream().filter(t -> t.from().equals(from)).map(WorkflowDefinition.Transition::to).distinct().toList());
            return WorkflowDecision.denied(from, to, "No configured transition from " + from + " to " + to + ". Available targets: " + (available.isEmpty() ? "none" : available));
        }
        if (!selected.roles().stream().anyMatch(role -> context.actor().hasRole(role) && (!role.equals("system") || context.actor().system())))
            return WorkflowDecision.denied(from, to, "Actor is not authorized for transition " + selected.id() + "; required roles: " + String.join(", ", selected.roles()));
        if (selected.id().equals(definition.cyclePolicy().transitionId()) && context.evidence().informationRequests() >= definition.cyclePolicy().maximum())
            return WorkflowDecision.denied(from, to, definition.cyclePolicy().errorMessage());
        for (String guard : selected.guards()) if (!guards.passes(guard, context))
            return WorkflowDecision.denied(from, to, definition.guards().get(guard));
        int cycles = selected.id().equals(definition.cyclePolicy().transitionId()) ? context.evidence().informationRequests() + 1 : 0;
        return new WorkflowDecision(true, selected.id(), from, to,
                selected.effects().stream().map(id -> effects.get(id).id()).toList(), null,
                cycles == 0 ? null : definition.cyclePolicy().counter(), cycles);
    }
    private List<String> failures(WorkflowDefinition.Transition t, WorkflowEvaluationContext c) {
        List<String> failed = new ArrayList<>();
        if (!t.roles().stream().anyMatch(role -> c.actor().hasRole(role) && (!role.equals("system") || c.actor().system()))) failed.add("Required roles: " + String.join(", ", t.roles()));
        if (t.id().equals(definition.cyclePolicy().transitionId()) && c.evidence().informationRequests() >= definition.cyclePolicy().maximum()) failed.add(definition.cyclePolicy().errorMessage());
        for (String guard : t.guards()) if (!guards.passes(guard,c)) failed.add(definition.guards().get(guard));
        return List.copyOf(failed);
    }
}
