        WorkflowDefinition d = parse(yaml());
        assertThat(d.states()).hasSize(8).contains("SUBMITTED", "CLOSED");
        assertThat(d.transitions()).hasSize(9);
        assertThatThrownBy(() -> d.states().add("INJECTED")).isInstanceOf(UnsupportedOperationException.class);
        assertThatThrownBy(() -> d.transitions().clear()).isInstanceOf(UnsupportedOperationException.class);
    }
